-- 01_schema.sql 을 먼저 실행한 뒤 이 파일을 실행하세요.
-- 다시 실행해도 안전합니다 (no 가 같으면 덮어씁니다).

on conflict (no) do update set
  camp = excluded.camp,
  from_date = excluded.from_date,
  to_date = excluded.to_date,
  send_date = excluded.send_date,
  ch = excluded.ch,
  gnb = excluded.gnb,
  cycle = excluded.cycle,
  "offer" = excluded."offer",
  qty = excluded.qty,
  team = excluded.team,
  mk = excluded.mk,
  hour = excluded.hour,
  status = excluded.status,
  adj_by = excluded.adj_by,
  reason = excluded.reason,
  note = excluded.note,
  adm_note = excluded.adm_note,
  memo = excluded.memo,
  moved = excluded.moved,
  req_at = excluded.req_at;

-- 다음 번호가 205 부터 나가도록 시퀀스를 맞춰 둔다
create sequence if not exists campaigns_no_seq;
select setval('campaigns_no_seq', (select coalesce(max(no),0) from campaigns));
alter table campaigns alter column no set default nextval('campaigns_no_seq');
